        // Three.js 초기화
        function initThreeJS() {
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0xf0f0f0);

            camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(80, 80, 80);

            renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
            document.getElementById('three-container').appendChild(renderer.domElement);

            controls = new THREE.OrbitControls(camera, renderer.domElement);
            controls.enableDamping = true;
            controls.dampingFactor = 0.05;
            controls.enableZoom = true;
            controls.enablePan = true;
            controls.minDistance = 20;
            controls.maxDistance = 200;
            controls.target.set(0, 25, 0);

            // 조명 추가
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
            scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(50, 100, 50);
            scene.add(directionalLight);

            const directionalLight2 = new THREE.DirectionalLight(0xffffff, 0.4);
            directionalLight2.position.set(-50, 50, -50);
            scene.add(directionalLight2);

            // 그리드 헬퍼 (선택적)
            const gridHelper = new THREE.GridHelper(100, 10, 0x888888, 0x444444);
            gridHelper.position.y = 0.01;
            scene.add(gridHelper);

            // 축 헬퍼
            const axesHelper = new THREE.AxesHelper(20);
            axesHelper.position.y = 0.01;
            scene.add(axesHelper);

            window.addEventListener('resize', onWindowResize);
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        // 모델 생성 함수들
        function createSitePlan() {
            const group = new THREE.Group();

            // 대지 경계 (간단한 직사각형)
            const siteSize = 200;
            const siteGeometry = new THREE.PlaneGeometry(siteSize, siteSize);
            const siteMaterial = new THREE.MeshBasicMaterial({ 
                color: 0x8bc34a, 
                side: THREE.DoubleSide,
                opacity: 0.3,
                transparent: true
            });
            const site = new THREE.Mesh(siteGeometry, siteMaterial);
            site.rotation.x = -Math.PI / 2;
            site.position.y = 0.01;
            group.add(site);

            // 건물 기초 위치 표시
            const buildingBaseSize = 60;
            const baseGeometry = new THREE.PlaneGeometry(buildingBaseSize, buildingBaseSize);
            const baseMaterial = new THREE.MeshBasicMaterial({ 
                color: 0xff9800, 
                side: THREE.DoubleSide,
                opacity: 0.6,
                transparent: true
            });
            const base = new THREE.Mesh(baseGeometry, baseMaterial);
            base.rotation.x = -Math.PI / 2;
            base.position.y = 0.02;
            group.add(base);

            // 건물 윤곽 (간단한 원통형으로 표현)
            const buildingGeometry = new THREE.CylinderGeometry(30, 15, 50, 32);
            const buildingMaterial = new THREE.MeshLambertMaterial({ color: 0x2196f3 });
            const building = new THREE.Mesh(buildingGeometry, buildingMaterial);
            building.position.y = 25;
            group.add(building);

            // 라벨 추가 (스프라이트 대신 간단한 텍스트용 평면)
            const label = makeTextSprite("롯데월드타워 위치", { 
                fontsize: 24, 
                borderColor: {r:0, g:0, b:0, a:0.8},
                backgroundColor: {r:255, g:255, b:255, a:0.9}
            });
            label.position.set(0, 30, 50);
            group.add(label);

            return group;
        }

        function createFloorPlanStage1() {
            const group = new THREE.Group();
            const height = 40; // 1~40층

            // 하부 구간: 거의 정사각형에 가까운 형태
            const width = 58; // 약간 tapered
            const depth = 58;

            const geometry = new THREE.BoxGeometry(width, height, depth);
            const material = new THREE.MeshLambertMaterial({ 
                color: 0x4caf50,
                opacity: 0.8,
                transparent: true
            });
            const cube = new THREE.Mesh(geometry, material);
            cube.position.y = height / 2;
            group.add(cube);

            // 평면도 표시를 위한 상단 평면
            const topGeometry = new THREE.PlaneGeometry(width, depth);
            const topMaterial = new THREE.MeshBasicMaterial({ 
                color: 0xffeb3b, 
                side: THREE.DoubleSide,
                opacity: 0.7,
                transparent: true
            });
            const top = new THREE.Mesh(topGeometry, topMaterial);
            top.rotation.x = -Math.PI / 2;
            top.position.y = height + 0.1;
            group.add(top);

            // 치수 표시
            const dimLabel = makeTextSprite(`하부 기준층: ${width}m × ${depth}m`, { 
                fontsize: 20, 
                borderColor: {r:0, g:0, b:0, a:0.7},
                backgroundColor: {r:255, g:255, b:255, a:0.8}
            });
            dimLabel.position.set(0, height/2, depth/2 + 10);
            group.add(dimLabel);

            return group;
        }

        function createFloorPlanStage2() {
            const group = new THREE.Group();
            const height = 40; // 41~80층

            // 중부 구간: 모서리가 잘려나간 팔각형에 가까운 형태
            const radius = 29; // 반지름
            const sides = 8;

            const shape = new THREE.Shape();
            const angleStep = (Math.PI * 2) / sides;
            for (let i = 0; i < sides; i++) {
                const angle = i * angleStep;
                const x = radius * Math.cos(angle);
                const y = radius * Math.sin(angle);
                if (i === 0) shape.moveTo(x, y);
                else shape.lineTo(x, y);
            }

            const extrudeSettings = {
                depth: height,
                bevelEnabled: false,
                steps: 1,
                bevelSize: 0,
                bevelThickness: 0
            };

            const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
            const material = new THREE.MeshLambertMaterial({ 
                color: 0xff9800,
                opacity: 0.8,
                transparent: true
            });
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.y = height / 2;
            group.add(mesh);

            // 상단 평면도
            const topShape = new THREE.Shape();
            for (let i = 0; i < sides; i++) {
                const angle = i * angleStep;
                const x = radius * Math.cos(angle);
                const y = radius * Math.sin(angle);
                if (i === 0) topShape.moveTo(x, y);
                else topShape.lineTo(x, y);
            }
            const topGeometry = new THREE.ShapeGeometry(topShape);
            const topMaterial = new THREE.MeshBasicMaterial({ 
                color: 0xffeb3b, 
                side: THREE.DoubleSide,
                opacity: 0.7,
                transparent: true
            });
            const top = new THREE.Mesh(topGeometry, topMaterial);
            top.rotation.x = -Math.PI / 2;
            top.position.y = height + 0.1;
            group.add(top);

            // 치수 표시
            const dimLabel = makeTextSprite(`중부 기준층: 약 ${Math.round(radius*2*Math.cos(Math.PI/8))}m × ${Math.round(radius*2*Math.cos(Math.PI/8))}m (팔각형)`, { 
                fontsize: 18, 
                borderColor: {r:0, g:0, b:0, a:0.7},
                backgroundColor: {r:255, g:255, b:255, a:0.8}
            });
            dimLabel.position.set(0, height/2, radius + 15);
            group.add(dimLabel);

            return group;
        }

        function createFloorPlanStage3() {
            const group = new THREE.Group();
            const height = 43; // 81~123층

            // 상부 구간: 훨씬 작은 정사각형 또는 원형에 가까운 형태
            const width = 22;
            const depth = 22;

            const geometry = new THREE.BoxGeometry(width, height, depth);
            const material = new THREE.MeshLambertMaterial({ 
                color: 0xf44336,
                opacity: 0.8,
                transparent: true
            });
            const cube = new THREE.Mesh(geometry, material);
            cube.position.y = height / 2;
            group.add(cube);

            // 상단 평면도
            const topGeometry = new THREE.PlaneGeometry(width, depth);
            const topMaterial = new THREE.MeshBasicMaterial({ 
                color: 0xffeb3b, 
                side: THREE.DoubleSide,
                opacity: 0.7,
                transparent: true
            });
            const top = new THREE.Mesh(topGeometry, topMaterial);
            top.rotation.x = -Math.PI / 2;
            top.position.y = height + 0.1;
            group.add(top);

            // 치수 표시
            const dimLabel = makeTextSprite(`상부 기준층: ${width}m × ${depth}m`, { 
                fontsize: 20, 
                borderColor: {r:0, g:0, b:0, a:0.7},
                backgroundColor: {r:255, g:255, b:255, a:0.8}
            });
            dimLabel.position.set(0, height/2, depth/2 + 8);
            group.add(dimLabel);

            return group;
        }

        function createElevation() {
            const group = new THREE.Group();
            const height = 55;

            // 세 개의 날개로 구성된 입면 표현
            const wingWidth = 18;
            const coreWidth = 12;

            // 왼쪽 날개
            const leftWing = new THREE.Mesh(
                new THREE.BoxGeometry(wingWidth, height, 8),
                new THREE.MeshLambertMaterial({ color: 0x9c27b0, opacity: 0.7, transparent: true })
            );
            leftWing.position.set(-(wingWidth/2 + coreWidth/2), height/2, 0);
            group.add(leftWing);

            // 중앙 코어
            const core = new THREE.Mesh(
                new THREE.BoxGeometry(coreWidth, height, 8),
                new THREE.MeshLambertMaterial({ color: 0x607d8b, opacity: 0.8, transparent: true })
            );
